15	
16	    private HouseholdNormalizer() {
17	    }
18	
19	    /**
20	     * The stable household identifier derived from an owner's last name and address. Owners with
21	     * equal {@link #key(String, String) keys} share the same id, and the id never changes for a given
22	     * household, so it can be recomputed for late joiners rather than stored and looked up.
23	     */
24	    public static String id(String lastName, String address) {
25	        return "H-" + sha256hex(key(lastName, address)).substring(0, 12).toUpperCase();
26	    }
27	
28	    private static String sha256hex(String value) {
29	        try {
30	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
31	            StringBuilder hex = new StringBuilder(digest.length * 2);
32	            for (byte b : digest) {
33	                hex.append(String.format("%02x", b));
34	            }
35	            return hex.toString();
36	        }
37	        catch (NoSuchAlgorithmException e) {
38	            throw new IllegalStateException("SHA-256 not available", e);
39	        }
40	    }
41	
42	    /**
43	     * Builds the canonical household key for an owner from its last name and address. Two owners
44	     * belong to the same household when their keys are equal. Either field may be {@code null}, which
45	     * normalizes to an empty token.
46	     */
47	    public static String key(String lastName, String address) {
48	        // '\n' separates the fields so that a boundary shift (e.g. "ab"+"c" vs "a"+"bc") cannot forge a
49	        // collision; it never appears in a normalized value.
50	        return normalize(lastName) + "\n" + normalize(address);
51	    }
52	
53	    /** Lower-cases and collapses whitespace to single spaces, trimming the ends; {@code null} → "". */
54	    private static String normalize(String value) {
55	        if (value == null) {
56	            return "";
57	        }
58	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
59	    }
