1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Canonical telephone normalization shared by the create pipeline: {@link NormalizeTelephone} stores
5	 * the E.164 form and {@link EnsureUniqueTelephone} compares by it. Not a pipeline step, so it is free
6	 * to expose plain helpers.
7	 */
8	public final class TelephoneNormalizer {
9	
10	    /** Minimum digits after the '+' for a valid E.164 number. */
11	    private static final int MIN_E164_DIGITS = 8;
12	
13	    /** Maximum digits after the '+' for a valid E.164 number. */
14	    private static final int MAX_E164_DIGITS = 15;
15	
16	    /** Default country code assumed when no leading '+' is present. */
17	    private static final String DEFAULT_COUNTRY_CODE = "61";
18	
19	    private TelephoneNormalizer() {
20	    }
21	
22	    /**
23	     * Converts a raw telephone to canonical E.164 form, or returns {@code null} when it cannot form a
24	     * valid E.164 number. A leading '+' and country code are kept when present; otherwise the default
25	     * country code '+61' is assumed and a single leading '0' is dropped from the national digits.
26	     * Spaces, dashes and brackets (any non-digit) are stripped. The result must have 8 to 15 digits
27	     * after the '+'.
28	     */
29	    public static String toE164(String telephone) {
30	        if (telephone == null) {
31	            return null;
32	        }
33	        boolean hasCountryCode = telephone.trim().startsWith("+");
34	        String digits = telephone.replaceAll("\\D", "");
35	        if (!hasCountryCode) {
36	            if (digits.startsWith("0")) {
37	                digits = digits.substring(1);
38	            }
39	            digits = DEFAULT_COUNTRY_CODE + digits;
40	        }
41	        if (digits.length() < MIN_E164_DIGITS || digits.length() > MAX_E164_DIGITS) {
42	            return null;
43	        }
44	        return "+" + digits;
45	    }
46	}
